<?php
require_once 'auth_check.php'; require_once __DIR__ . '/app/partials.php';
$conn=getDBConnection(); $q=trim($_GET['q']??''); $where=''; if($q!==''){ $term=$conn->real_escape_string($q); $where=" WHERE full_name LIKE '%{$term}%' OR phone LIKE '%{$term}%'"; }
$donors=$conn->query("SELECT donor_id,full_name,phone,address,created_at FROM donors{$where} ORDER BY created_at DESC LIMIT 200");
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Donor Directory</title><link rel="stylesheet" href="css/donor.css"><style>.content{margin-left:250px;padding:24px}.table-container{overflow:auto}table{width:100%;background:#fff}.search{margin:12px 0}.search input,.search button{padding:9px}</style></head><body><div class="dashboard-container"><?php render_admin_sidebar('donors'); ?><main class="content"><h1>Donor Directory</h1><p>A reusable donor record is linked to each donation by its unique donor ID.</p><form class="search" method="get"><input name="q" value="<?=e($q)?>" placeholder="Name or phone"><button>Search</button></form><div class="table-container"><table><thead><tr><th>Donor</th><th>Phone</th><th>Address</th><th>Joined</th><th>Donation history</th></tr></thead><tbody><?php if($donors->num_rows===0):?><tr><td colspan="5">No donor records found.</td></tr><?php else: while($donor=$donors->fetch_assoc()):?><tr><td><?=e($donor['full_name'])?></td><td><?=e($donor['phone'])?></td><td><?=e($donor['address'])?></td><td><?=e($donor['created_at'])?></td><td><a href="donation_ledger.php?q=<?=e(urlencode($donor['phone']))?>">View donations</a></td></tr><?php endwhile;endif;?></tbody></table></div></main></div></body></html><?php $conn->close();?>
